"""Static review renditions of the same editable founder-profile.json used by Filament."""

def spotlight(f, U, E):
    photo=E(f.get('headshot_url') or f.get('portrait_url'))
    return f'''<section class="x-founder-spotlight" aria-labelledby="meet-kristine-home">
      <div class="x-founder-spotlight__visual"><img src="{photo}" alt="Kristine Vowles, Founder and CEO of The Luxury Look" width="800" height="1000" decoding="async" loading="lazy"><span>KRISTINE VOWLES / FOUNDER &amp; CEO</span></div>
      <div class="x-founder-spotlight__copy"><span class="x-eyebrow">03 / THE PERSON BEHIND THE WORK</span><h2 id="meet-kristine-home">Meet<br><em>Kristine Vowles.</em></h2><p class="x-founder-spotlight__lead">{E(f['headline'])}</p><p>{E(f['short_bio'])}</p>
      <div class="x-founder-spotlight__proof"><span><strong>{E(f['founding_year'])}</strong> THE LUXURY LOOK FOUNDED</span><span><strong>{E(f['experience_label'])}</strong> INDUSTRY EXPERIENCE</span></div>
      <div class="x-founder-spotlight__actions"><a class="x-pill" href="{U('about')}#meet-kristine">Meet Kristine <span>↗</span></a><button type="button" class="x-founder-film-link" data-video-url="{E(f['interview_url'])}" data-video-title="Kristine Vowles / Sedona Staging Interview"><span aria-hidden="true">▶</span> Watch Kristine on film</button></div></div>
    </section>'''


def about(f, videos, U, E):
    principles=''.join(f'<div><span>{i+1:02d}</span><div><h3>{E(pr.get("title"))}</h3><p>{E(pr.get("description"))}</p></div></div>' for i,pr in enumerate(f.get('principles',[])))
    second=next((v for v in videos if 'gNeiecujx8Q' in v.get('video_url','')),None)
    secondary=''
    if second:
        secondary=(f'<section class="x-founder-video-encore x-wrap x-section"><div><span class="x-eyebrow">05 / A PROJECT IN MOTION</span><h2>A transformation<br><em>worth seeing.</em></h2><p>A walk through Studio 3125—an example of the kind of spaces that make up the studio’s body of work.</p></div>'
          f'<div class="x-founder-interview__visual"><img src="{E(second.get("poster_url"))}" width="1280" height="720" loading="lazy" alt="Studio 3125 transformation video poster"><button type="button" class="x-film-cta" data-video-url="{E(second.get("video_url"))}" data-video-title="Studio 3125 Tour"><span class="x-play-icon">▶</span> Watch the Studio 3125 tour</button></div></section>')
    return f'''<article class="x-founder-page">
      <header class="x-founder-hero" aria-labelledby="founder-title"><div class="x-founder-hero__copy"><span class="x-eyebrow">THE LUXURY LOOK / MEET THE FOUNDER</span><p class="x-founder-hero__intro">The vision starts with a person.</p><h1 id="founder-title">Kristine<br><em>Vowles.</em></h1><p class="x-founder-hero__role">{E(f['role'])}</p><p class="x-founder-hero__lead">{E(f['lead'])}</p><div class="x-founder-hero__actions"><a class="x-pill" href="{U('contact')}">Begin Your Project <span>↗</span></a><a class="x-underlink" href="#meet-kristine">Get to know Kristine ↓</a></div></div>
       <div class="x-founder-hero__portrait"><img src="{E(f['portrait_url'])}" alt="Kristine Vowles, founder and CEO, in a portrait from The Luxury Look's published About page" width="850" height="1050" decoding="async" fetchpriority="high"><div class="x-founder-hero__portrait-caption">KRISTINE VOWLES <span>FOUNDER / DESIGNER / STRATEGIST</span></div></div></header>
       <section class="x-founder-credentials x-wrap" aria-label="Professional background"><div><strong>{E(f['founding_year'])}</strong><span>THE LUXURY LOOK ESTABLISHED</span></div><div><strong>{E(f['experience_label'])}</strong><span>EXPERIENCE IN DESIGN &amp; REAL ESTATE</span></div><div><strong>Personal by design</strong><span>INTERIORS / STAGING / SOURCING</span></div></section>
       <section id="meet-kristine" class="x-founder-biography x-wrap x-section"><div class="x-founder-biography__heading"><span class="x-eyebrow">01 / THE STORY</span><h2>Built on experience.<br><em>Driven by imagination.</em></h2><p>{E(f['short_bio'])}</p></div><div class="x-founder-biography__text"><h3>From real estate<br>to real spaces.</h3><p>{E(f['career_bio'])}</p><h3>The philosophy behind the work.</h3><p>{E(f['approach_bio'])}</p></div></section>
       <section class="x-founder-perspective" aria-label="Kristine's approach"><figure class="x-founder-perspective__image"><img src="{E(f['secondary_photo_url'])}" alt="A second portrait of Kristine Vowles from The Luxury Look's original About page" width="800" height="1000" loading="lazy" decoding="async"><figcaption>KRISTINE VOWLES / THE LUXURY LOOK</figcaption></figure><div class="x-founder-perspective__copy"><span class="x-eyebrow">02 / HER POINT OF VIEW</span><h2>Design is about<br><em>more than the room.</em></h2><p>Careful listening. A practiced eye. Respect for the way a space will be lived in and remembered.</p><div class="x-founder-principles">{principles}</div></div></section>
       <section class="x-founder-interview x-wrap x-section" aria-label="Kristine on film"><div class="x-founder-interview__copy"><span class="x-eyebrow">03 / IN CONVERSATION</span><h2>Hear the perspective<br><em>from Kristine herself.</em></h2><p>In this published interview about luxury staging in Sedona, Kristine talks about how she approaches properties and the people who experience them.</p><p class="x-founder-interview__meta">A FILMED CONVERSATION / LUXURY STAGING IN SEDONA</p></div><div class="x-founder-interview__visual"><img src="{E(f['interview_poster_url'])}" alt="Staging Luxury Homes in Sedona with Kristine Vowles — video thumbnail" width="1280" height="720" loading="lazy"><button type="button" class="x-film-cta" data-video-url="{E(f['interview_url'])}" data-video-title="Staging Luxury Homes in Sedona with Kristine Vowles"><span class="x-play-icon">▶</span> Watch Kristine's interview</button></div></section>
       <section class="x-founder-beyond x-section"><div class="x-wrap x-founder-beyond__layout"><div><span class="x-eyebrow">04 / BEYOND THE STUDIO</span><h2>A passion for<br><em>sharing what she knows.</em></h2></div><div><p>{E(f['beyond_bio'])}</p><div class="x-founder-beyond__links"><a href="{U('buying-trips')}">Discover Buying Trips <span>↗</span></a><a href="{U('education')}">Explore Education &amp; Workshops <span>↗</span></a></div></div></div></section>
       {secondary}
       <section class="x-founder-next x-wrap x-section"><div><span class="x-eyebrow">WHAT COULD THIS LOOK LIKE FOR YOU?</span><h2>Experience worth<br><em>inviting into your home.</em></h2></div><div><p>Whether you are building, renovating, furnishing a second home or preparing a property for market, your project deserves someone who takes the time to understand it.</p><a class="x-pill" href="{U('contact')}">Start a conversation <span>↗</span></a></div></section>
    </article>'''
